package com.mediassistrover.backend.service.impl;
import com.mediassistrover.backend.dto.common.DeletionContracts.*;import com.mediassistrover.backend.enums.JobStatus;import com.mediassistrover.backend.exception.*;import com.mediassistrover.backend.repository.JobRepository;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.nio.ByteBuffer;import java.util.*;import java.util.UUID;
@Service @RequiredArgsConstructor public class ServiceRequestHardDeleteService {private final JdbcTemplate jdbc;private final JobRepository jobs;private final JobHardDeleteService jobDelete;
 @Transactional(readOnly=true) public DeletionImpactResponse impact(UUID id){byte[]k=key(id);exists(k,id);List<com.mediassistrover.backend.entity.Job> js=jobs.findByServiceRequestServiceRequestId(id);var d=new LinkedHashMap<String,Long>();d.put("jobs",(long)js.size());d.put("alerts",count("Alert","service_request_id",k));d.put("voiceCommands",count("VoiceCommand","service_request_id",k));List<String>b=new ArrayList<>();if(js.stream().anyMatch(j->!Set.of(JobStatus.SUCCEEDED,JobStatus.FAILED,JobStatus.CANCELLED).contains(j.getStatus())))b.add("ServiceRequest has active Job");if(count("Alert","service_request_id",k)>0)b.add("ServiceRequest has Alert; delete closed Alert first");if(count("VoiceCommand","service_request_id",k)>0)b.add("ServiceRequest has VoiceCommand; delete VoiceInteraction first");return new DeletionImpactResponse(id,"ServiceRequest",b.isEmpty(),b,Map.copyOf(d));}
 @Transactional(propagation=Propagation.MANDATORY) public HardDeleteResponse delete(UUID id){byte[]k=key(id);lock(k,id);var i=impact(id);if(!i.canHardDelete())throw new ConflictException(String.join(", ",i.blockers()));var d=new LinkedHashMap<String,Long>();for(var job:jobs.findByServiceRequestServiceRequestId(id)){HardDeleteResponse r=jobDelete.delete(job.getJobId());r.deleted().forEach((n,c)->d.merge(n,c,Long::sum));}d.put("DeliveryItem",del("DELETE di FROM DeliveryItem di JOIN DeliveryRequest dr ON di.delivery_request_id=dr.service_request_id WHERE dr.service_request_id=?",k));d.put("DeliveryRequest",del("DELETE FROM DeliveryRequest WHERE service_request_id=?",k));d.put("NavigationRequest",del("DELETE FROM NavigationRequest WHERE service_request_id=?",k));d.put("EscortRequest",del("DELETE FROM EscortRequest WHERE service_request_id=?",k));d.put("ServiceRequest",del("DELETE FROM ServiceRequest WHERE service_request_id=?",k));return new HardDeleteResponse(id,"ServiceRequest",Map.copyOf(d));}
 private long count(String t,String c,byte[]k){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+t+"` WHERE `"+c+"`=?",Long.class,k);return n==null?0:n;}private long del(String q,byte[]k){return jdbc.update(q,k);}private void exists(byte[]k,UUID id){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM ServiceRequest WHERE service_request_id=?",Long.class,k);if(n==null||n==0)throw new ResourceNotFoundException("ServiceRequest not found: "+id);}private void lock(byte[]k,UUID id){if(jdbc.query("SELECT service_request_id FROM ServiceRequest WHERE service_request_id=? FOR UPDATE",(r,n)->r.getBytes(1),k).isEmpty())throw new ResourceNotFoundException("ServiceRequest not found: "+id);}private static byte[]key(UUID id){return ByteBuffer.allocate(16).putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).array();}}
